  ionViewWillLeave() {
    this.closingBuildID = null;
    if (this.toastinstance) {
      this.toastinstance.dismiss();
    }
  }

  async presentToastWithOptions(buildId, buildName, id) {
    if (this.toastinstance) {
      this.toastinstance.dismiss();
    }
    let text = id == 1 ? 'B ' + buildId + ' ' + buildName + ' opened' : 'B ' + buildId + ' ' + buildName + ' closed';
    this.toastinstance = await this.toastController.create({
      header: text,
      position: 'bottom',
      cssClass: 'my-toast',
      color: 'light',
      duration: id == 1 ? null : 1000,
      buttons: [
        {
          text: 'Dismiss',
          role: 'cancel',
          handler: () => {
            console.log('Cancel clicked');
          }
        }
      ]
    });
    this.toastinstance.present();
  }

